const sourceName = msg.metadata.source.name || msg.metadata.source.identifier;
const now = Date.now();

msg.payload = {
    id:        'pb-att-' + now + '-src-up-' + Math.random().toString(36).slice(2, 5),
    text:      '\u2705 Tilkoblingen til ' + sourceName + ' er gjenopprettet.',
    timestamp: now,
    author:    'System-melding',
    files:     [],
    labels:    []
};

msg.metadata = {
    source: { client_system: 'parat-bridge', name: 'parat_bridge', identifier: 'parat_bridge' },
    target: msg.metadata.target,
    connection_name: msg.metadata.connection_name
};

return msg;
